import{z as d,x as E,o as n,c as h,q as l,j as o,D as a,d as i,s,S as p,b as t}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"HTTP/1.1 持久连接与分块","description":"","frontmatter":{"title":"HTTP/1.1 持久连接与分块","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/http11-persistent-chunked.md","filePath":"cs/http11-persistent-chunked.md","lastUpdated":1791413859000}'),c={name:"cs/http11-persistent-chunked.md"};function B(T,e,A,C,u,k){const r=E("Mermaid");return n(),h("div",null,[e[2]||(e[2]=l('<h1 id="http-1-1-持久连接与分块" tabindex="-1">HTTP/1.1 持久连接与分块 <a class="header-anchor" href="#http-1-1-持久连接与分块" aria-label="Permalink to &quot;HTTP/1.1 持久连接与分块&quot;">​</a></h1><div class="epigraph"><p>默认保持 TCP 连接复用多个请求；长度未知时用 chunked 编码分块结束，而不再靠关闭连接当 EOF。</p><footer>—— 据 RFC 9112 HTTP/1.1；RFC 2616 历史对照整理</footer></div><p>主干<a href="/cs/http">HTTP</a> 给语义。<a href="/cs/tcp-wireless">上一课</a> 结束传输进阶。缺口是 <strong>1.1 怎么把消息映到字节流</strong>：Connection: keep-alive 成默认、Content-Length vs chunked。本课不把队头阻塞写完，下一课写。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>HTTP/1.0 常一请求一连接，握手与慢启动税重。<a href="/cs/bandwidth-delay-product">BDP</a> 刚填满就拆。1.1：持久连接上串行请求；报文体要么事先长度，要么 <code>Transfer-Encoding: chunked</code> 用 0 块结束。管道化（pipelining）允许一次排多个请求，但响应必须顺序——HOL 下一课。分块让动态页面不必先算全长。</p><p><span class="marginnote">术语翻译：成帧（framing）就是在连续的字节流里切出报文边界的手法。TCP 只保证字节按序到达，不告诉你「这条消息到哪结束」——Content-Length 与 chunked 是 HTTP 自己补上的两种切法，一个是「事先说好总长」，一个是「边切边报每段长」。</span></p><p>不要把持久连接写成 TCP keepalive。</p><p><span class="marginnote">RFC 9112。chunk 大小十六进制。本课不把废弃的 identity 编码展开。</span></p><h3 id="不是-tcp-keepalive" tabindex="-1">不是 TCP keepalive <a class="header-anchor" href="#不是-tcp-keepalive" aria-label="Permalink to &quot;不是 TCP keepalive&quot;">​</a></h3><p>持久连接摊销握手。chunked 提供无先验长度的成帧。管道化顺序响应，现实常关。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：握手一次 → 多请求 → 长度或分块。对照 TSO：大 write 仍是一请求体。与 MSS 无关直接，但小请求头税相对大。</p>',12)),(n(),o(p,null,{default:a(()=>[s(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20TCP%5B%22%E4%B8%80%E6%9D%A1%20TCP%22%5D%20--%3E%20R1%5B%22%E8%AF%B7%E6%B1%82%201%22%5D%0A%20%20R1%20--%3E%20R2%5B%22%E8%AF%B7%E6%B1%82%202%22%5D%0A%20%20BODY%5B%22%E6%AD%A3%E6%96%87%22%5D%20--%3E%20CL%5B%22Content-Length%22%5D%0A%20%20BODY%20--%3E%20CH%5B%22chunked%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=t("h2",{id:"机制",tabindex:"-1"},[i("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=t("p",null,"中间代理必须理解分块才能复用连接。TLS 入口在持久连接上摊销握手，动机与 QUIC 1-RTT 同类但层不同。无线掉线后半开，1.1 连接死，应用重开。SYN cookies 只影响新握手次数，持久化减少握手。",-1)),e[5]||(e[5]=t("p",null,"没有 Content-Length 时，接收方靠什么知道报文在哪结束？",-1)),(n(),o(p,null,{default:a(()=>[s(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E5%93%8D%E5%BA%94%E5%BC%80%E5%A7%8B%EF%BC%9A%E5%A4%B4%E9%87%8C%E5%86%99%E6%98%8E%20chunked%22%5D%20--%3E%20C1%5B%22%E5%9D%97%201%EF%BC%9A%E5%8D%81%E5%85%AD%E8%BF%9B%E5%88%B6%E9%95%BF%E5%BA%A6%E8%A1%8C%20%2B%20%E6%95%B0%E6%8D%AE%22%5D%0A%20%20C1%20--%3E%20C2%5B%22%E5%9D%97%202%EF%BC%9A%E9%95%BF%E5%BA%A6%E8%A1%8C%20%2B%20%E6%95%B0%E6%8D%AE%22%5D%0A%20%20C2%20--%3E%20T%5B%22%E7%BB%88%E6%AD%A2%E5%9D%97%EF%BC%9A%E9%95%BF%E5%BA%A6%200%22%5D%0A%20%20T%20--%3E%20DONE%5B%22%E6%8A%A5%E6%96%87%E7%BB%93%E6%9D%9F%EF%BC%8C%E8%BF%9E%E6%8E%A5%E5%8F%AF%E7%BB%A7%E7%BB%AD%E5%A4%8D%E7%94%A8%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[i(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=l('<p><span class="marginnote">数字实例：发「Hello」用 chunked 上线就是 <code>5\\r\\nHello\\r\\n0\\r\\n\\r\\n</code>——先声明这块有 5 字节，再给数据；长度为 0 的块是「读完了」的暗号。这就是成帧：在一条字节流里切出「这条报文到此为止」的边界。</span></p><p>安全：未授权的连接复用要把认证绑对（后课 Cookie）。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 HTTP/1.1 升级头的全部。队头阻塞对照是下一课。后课默认：1.1 默认持久；未知长度用分块。</p><p>管道化在现实中常关，因 HOL 与坏代理。</p><p>下一课<a href="/cs/hol-blocking">队头阻塞对照</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>持久连接摊销握手与慢启动。</li><li>chunked 提供无先验长度的成帧。</li><li>管道化顺序响应，HOL 留给下一课。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 9112。</li></ul><p><span class="marginnote">常见误区：把 HTTP 的 <code>Connection: keep-alive</code> 与 TCP 的 keepalive 混为一谈。前者是应用层「这条连接别拆，我还要接着发请求」；后者是传输层的空包探测，用来发现死连接。一个省握手，一个查生死，完全两回事。</span></p>',9))])}const P=d(c,[["render",B]]);export{m as __pageData,P as default};
